const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".app{width:100%;height:100%;min-width:0;min-height:0;box-sizing:border-box;padding:8px;display:flex;flex-direction:column;gap:6px;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.app *{box-sizing:border-box}\n.app.s3x3{padding:6px;gap:4px}\n.app.s3x6,.app.s6x6{font-size:13px}\n.app.s6x6,.app.s6x3{padding:10px}\n.app.s6x3{padding:8px}\n.pane{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.s3x3 .pane{gap:4px}\n\n.btn{font:inherit;font-size:12px;height:26px;padding:0 9px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;white-space:nowrap;overflow:hidden;flex:none;display:inline-flex;align-items:center;justify-content:center;line-height:1}\n.btn.ic{width:26px;padding:0}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:700}\n.btn.on{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.btn.danger{border-color:var(--ink);font-weight:700}\n.btn:disabled{opacity:.4;cursor:default}\n.s6x6 .btn,.s3x6 .btn{height:28px}\n.s6x6 .btn.ic,.s3x6 .btn.ic{width:28px}\n.btn:focus-visible,.vrow:focus-visible,.omain:focus-visible,.in:focus-visible,.seg button:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.bar{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.nm{flex:1;min-width:0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub{color:var(--muted);font-size:11px;flex:none}\n.mut{color:var(--muted)}\n.c1{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.c2{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain}\n.rows{display:flex;flex-direction:column;gap:6px}\n.rows>*{flex:none}\n\n.vrow{display:flex;align-items:center;gap:6px;width:100%;text-align:left;font:inherit;color:inherit;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);cursor:pointer;min-width:0}\n.vrow.sel{border-color:var(--accent);background:var(--soft)}\n.vmain{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}\n.vmain b{font-size:13px}\n.pick{font-size:11px}\n.chev{color:var(--muted);font-size:18px;flex:none}\n\n.ctl{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:8px;overflow:hidden;flex:none}\n.seg button{font:inherit;font-size:12px;height:24px;padding:0 8px;border:0;background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer}\n.seg button.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n.pg{margin-left:auto;display:flex;align-items:center;gap:3px}\n.pgt{font-size:11px;color:var(--muted);min-width:34px;text-align:center;white-space:nowrap}\n.s3x3 .ctl{justify-content:space-between}\n.s3x3 .btn.ic{width:24px;height:24px}\n\n.menu{display:flex;flex-wrap:wrap;align-items:center;gap:6px;flex:none;padding:5px 6px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.warn{flex:1 1 auto;font-size:12px;min-width:0}\n\n.orow{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);padding:4px 4px 4px 6px;min-width:0}\n.orow.sel{border-color:var(--accent);background:var(--soft)}\n.omain{flex:1;min-width:0;display:flex;align-items:center;gap:6px;text-align:left;font:inherit;color:inherit;background:none;border:0;padding:2px;cursor:pointer}\n.otx{flex:1;min-width:0;display:flex;flex-direction:column}\n.star{font-size:15px}\n\n.lb{flex:none;min-width:22px;height:22px;padding:0 5px;border-radius:11px;display:inline-flex;align-items:center;justify-content:center;gap:1px;font-weight:800;font-size:12px;background:var(--soft);color:var(--ink);border:1px solid var(--line)}\n.lb i{font-style:normal;font-size:10px}\n.sel .lb{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n\n.cards{flex:1;min-height:0;min-width:0;display:flex;gap:6px}\n.cards>.opt{flex:1 1 0;min-width:0}\n.cards.all{flex-direction:column;gap:8px;padding:1px}\n.cards.all>.opt{flex:none}\n.s6x6 .cards.all{display:grid;grid-template-columns:1fr 1fr;align-content:start;gap:8px}\n\n.opt{display:flex;flex-direction:column;min-width:0;min-height:0;border:1px solid var(--line);border-radius:12px;background:var(--panel-paper);overflow:hidden}\n.opt.sel{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.oh{display:flex;align-items:center;gap:6px;padding:6px 8px 2px;flex:none}\n.tag{font-size:11px;color:var(--muted)}\n.opt.sel .tag{color:var(--ink);font-weight:700}\n.ob{flex:1;min-height:0;overflow:auto;padding:2px 8px 6px;display:flex;flex-direction:column;gap:6px}\n.ob>*{flex:none}\n.fb{min-width:0}\n.fl{display:flex;justify-content:space-between;align-items:baseline;gap:6px;color:var(--muted);font-size:11px}\n.fl em{font-style:normal}\n.ft{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}\n.ft.title{font-weight:700;font-size:14px}\n.ft.none,.cover.none{color:var(--muted);font-weight:400}\n.cover{display:flex;align-items:center;justify-content:center;text-align:center;min-height:38px;padding:8px;margin-top:2px;border-radius:8px;background:var(--soft);color:var(--ink);border:1px dashed var(--line);font-weight:800;font-size:16px;line-height:1.25;overflow-wrap:anywhere;white-space:pre-wrap}\n.opt.sel .cover{background:var(--accent);color:var(--on-accent);border:1px solid var(--accent)}\n.opt.sel .cover.none{color:var(--on-accent)}\n.s3x6 .cover,.s6x6 .cover{aspect-ratio:16/9}\n.acts{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:4px;padding:6px 8px 8px;border-top:1px solid var(--line)}\n.acts .btn{flex:1 1 auto;padding:0 6px}\n.s6x3 .acts{padding:4px 6px 6px}\n.s6x3 .cover,.s3x3 .cover{font-size:14px;min-height:32px;padding:6px}\n\n.s3x3 .opt{display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto minmax(0,1fr)}\n.s3x3 .oh{grid-column:1;grid-row:1;padding:4px 0 2px 6px}\n.s3x3 .tag{display:none}\n.s3x3 .acts{grid-column:2;grid-row:1;border:0;padding:4px 4px 2px 4px;flex-wrap:nowrap;justify-content:flex-end;gap:3px}\n.s3x3 .acts .btn{flex:1 1 0;min-width:0;padding:0 2px;font-size:11px;height:24px}\n.s3x3 .warn{font-size:11px;white-space:nowrap}\n.s3x3 .ob{grid-column:1 / -1;grid-row:2;padding:2px 6px 6px}\n\n.empty{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;color:var(--muted);padding:6px}\n.empty p{margin:0}\n.empty>:first-child{margin-top:auto}\n.empty>:last-child{margin-bottom:auto}\n\n.err{flex:none;padding:4px 8px;border:1px solid var(--ink);border-radius:8px;font-size:12px;background:var(--panel-paper);color:var(--ink)}\n.err:empty{display:none}\n\n.fields{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;align-content:start}\n.s6x3 .fields,.s6x6 .fields{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld.wide{grid-column:1 / -1}\n.in{width:100%;font:inherit;font-size:13px;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px;padding:6px 8px;min-width:0;resize:vertical}\n.s6x6 .in{font-size:14px;padding:8px 10px}\n";
function mount(ctx){
const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
const h=(t,a,...c)=>el(t,a||{},...c.flat(Infinity).filter(x=>x!=null&&x!==false));
const small=size==='3x3',narrow=size==='3x3'||size==='3x6';
const paged=size==='3x3'||size==='6x3',per=size==='6x3'?2:1;
const lab=i=>i<26?String.fromCharCode(65+i):String(i+1);
const len=t=>Array.from(t||'').length;
const clampN=(x,a,b)=>Math.max(a,Math.min(b,x));
function norm(s){
  const vs=s&&Array.isArray(s.videos)?s.videos:[];
  return {...(s||{}),videos:vs.map(v=>({...v,options:Array.isArray(v.options)?v.options:[]}))};
}
function selOf(v){return v.options.find(o=>o.id===v.selectedId)||null;}
function nm(o){return o.title||o.cover||o.idea||'（空方案）';}
function mapV(s,id,fn){const n=norm(s);return {...n,videos:n.videos.map(v=>v.id===id?fn(v):v)};}
function btn(t,fn,cls,x){
  return h('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick:fn},x||{}),t);
}
function go(p){Object.assign(ui,p);ui.err='';redraw();}
function act(fn,next){
  ui.err='';
  const p=next?commit(fn,next):update(fn);
  return Promise.resolve(p).catch(()=>{ui.err='保存失败，已保留原内容，请重试';redraw();return false;});
}
function skey(){return (ui.view||'list')+':'+(ui.vid||'')+':'+(ui.mode==='all'?'all':'one');}

function toggleSel(vid,oid){
  return act(s=>mapV(s,vid,v=>({...v,selectedId:v.selectedId===oid?null:oid})));
}
function dupOpt(vid,oid,idx){
  const id=uid();
  return act(s=>mapV(s,vid,v=>{
    const o=v.options.find(x=>x.id===oid);
    if(!o)return v;
    const a=v.options.slice();
    a.splice(idx+1,0,{...o,id,created:day()});
    return {...v,options:a};
  }),{...ui,start:idx+1,confirm:null});
}
function delOpt(vid,oid){
  return act(s=>mapV(s,vid,v=>({
    ...v,
    options:v.options.filter(x=>x.id!==oid),
    selectedId:v.selectedId===oid?null:v.selectedId
  })),{...ui,confirm:null});
}
function delVid(vid){
  return act(s=>{const n=norm(s);return {...n,videos:n.videos.filter(v=>v.id!==vid)};},
    {...ui,view:'list',vid:null,vmenu:false,confirm:null});
}
function openV(v){go({view:'vform',draft:{name:v?v.name:''},editId:v?v.id:null,formErr:'',confirm:null});}
function openO(vid,o){
  go({view:'oform',vid,oid:o?o.id:null,formErr:'',
    draft:{title:o?o.title:'',cover:o?o.cover:'',idea:o?o.idea:''}});
}
function openVid(id){go({view:'video',vid:id,start:0,mode:'one',vmenu:false,confirm:null,draft:null});}

function form(title,fields,onSave,onBack,saveLabel){
  const d=ui.draft||(ui.draft={});
  const err=h('div',{class:'err',role:'alert'},ui.formErr||'');
  let busy=false;
  function save(){
    if(busy)return;
    const r=onSave(d);
    if(typeof r==='string'){err.textContent='⚠ '+r;return;}
    busy=true;err.textContent='';
    Promise.resolve(r).then(ok=>{busy=false;if(ok===false)err.textContent='⚠ 保存失败，内容已保留，请重试';});
  }
  const rows=fields.map(f=>{
    const cnt=f.count?h('span',{class:'cnt'}):null;
    const upd=()=>{if(cnt)cnt.textContent=len(d[f.key])+' 字';};
    const attrs={class:'in',value:d[f.key]||'',placeholder:f.ph||'','aria-label':f.label,
      oninput:e=>{d[f.key]=e.target.value;upd();}};
    const inp=f.area
      ?h('textarea',{...attrs,rows:f.rows||3})
      :h('input',{...attrs,type:'text',onkeydown:e=>{if(e.key==='Enter'){e.preventDefault();save();}}});
    upd();
    return h('label',{class:'fld'+(f.wide?' wide':'')},h('span',{class:'fl'},f.label,cnt),inp);
  });
  return h('div',{class:'pane'},
    h('div',{class:'bar'},
      btn('‹',onBack,'ic',{'aria-label':'返回，不保存'}),
      h('div',{class:'nm'},title),
      btn(saveLabel||'保存',save,'pri')),
    err,
    h('div',{class:'scroll fields'},...rows));
}


function vform(S){
  const ed=ui.editId?S.videos.find(x=>x.id===ui.editId):null;
  return form(ed?'改名':'新视频',[{key:'name',label:'视频名称',ph:'这条视频叫什么'}],d=>{
    const name=(d.name||'').trim();
    if(!name)return '请先填写视频名称';
    if(ed)return act(s=>mapV(s,ed.id,x=>({...x,name})),
      {...ui,view:'video',draft:null,formErr:'',vmenu:false});
    const id=uid();
    return act(s=>{
      const n=norm(s);
      return {...n,videos:[{id,name,created:day(),options:[],selectedId:null},...n.videos]};
    },{...ui,view:'oform',vid:id,oid:null,draft:{title:'',cover:'',idea:''},formErr:'',
      start:0,mode:'one',vmenu:false,confirm:null});
  },()=>go({view:ed?'video':'list',draft:null,formErr:''}),ed?'保存':'创建');
}
function oform(S){
  const v=S.videos.find(x=>x.id===ui.vid);
  if(!v){ui.view='list';return listView(S);}
  const ed=ui.oid?v.options.find(x=>x.id===ui.oid):null;
  return form(ed?'编辑方案 '+lab(v.options.indexOf(ed)):'新增方案',[
    {key:'title',label:'标题',ph:'备选标题',count:1},
    {key:'cover',label:'封面短句',ph:'封面上的大字',count:1},
    {key:'idea',label:'画面想法',ph:'画面、构图、素材、配色',area:1,rows:4,wide:1}
  ],d=>{
    const t=(d.title||'').trim(),c=(d.cover||'').trim(),i=(d.idea||'').trim();
    if(!t&&!c&&!i)return '标题、封面短句、画面想法至少填一项';
    if(ed)return act(s=>mapV(s,v.id,x=>({...x,options:x.options.map(o=>o.id===ed.id?{...o,title:t,cover:c,idea:i}:o)})),
      {...ui,view:'video',draft:null,formErr:'',vmenu:false});
    const id=uid();
    ui.sct=ui.sct||{};
    ui.sct['video:'+v.id+':one']=1e9;
    return act(s=>mapV(s,v.id,x=>({...x,options:[...x.options,{id,title:t,cover:c,idea:i,created:day()}]})),
      {...ui,view:'video',draft:null,formErr:'',mode:'one',start:v.options.length,vmenu:false,confirm:null});
  },()=>go({view:'video',draft:null,formErr:''}));
}

function vrow(v){
  const o=selOf(v),n=v.options.length;
  return h('button',{type:'button',class:'vrow'+(o?' sel':''),onclick:()=>openVid(v.id)},
    h('span',{class:'vmain'},
      h('b',{class:'c1'},v.name),
      h('span',{class:'c1 mut'},n?n+' 套方案 · '+(o?'已选 '+lab(v.options.indexOf(o)):'未选定'):'暂无方案'),
      o?h('span',{class:'c2 pick'},'★ '+nm(o)):null),
    h('span',{class:'chev','aria-hidden':'true'},'›'));
}
function listView(S){
  const vs=S.videos,done=vs.filter(v=>selOf(v)).length;
  return h('div',{class:'pane'},
    h('div',{class:'bar'},
      h('div',{class:'nm'},'标题封面备选'),
      btn(narrow?'＋':'＋ 新视频',()=>openV(null),'pri'+(narrow?' ic':''),{'aria-label':'新增视频'})),
    vs.length?h('div',{class:'sub'},vs.length+' 个视频 · '+done+' 个已选定'):null,
    vs.length
      ?h('div',{class:'scroll rows'},...vs.map(vrow))
      :h('div',{class:'empty'},
        h('p',{},'还没有视频。先添加一条，再往里放几套标题、封面短句和画面想法。'),
        btn('添加第一条视频',()=>openV(null),'pri')));
}


function fb(label,val,cls,cnt){
  return h('div',{class:'fb'},
    h('div',{class:'fl'},label,cnt&&val?h('em',{},len(val)+' 字'):null),
    h('div',{class:(cls||'ft')+(val?'':' none')},val||'（未填）'));
}
function card(v,o,i){
  const sel=v.selectedId===o.id;
  const cf=ui.confirm&&ui.confirm.t==='o'&&ui.confirm.id===o.id;
  const acts=cf
    ?h('div',{class:'acts'},
      h('span',{class:'warn'},'⚠ 删除这套？'),
      btn('删除',()=>delOpt(v.id,o.id),'danger'),
      btn('取消',()=>go({confirm:null})))
    :h('div',{class:'acts'},
      btn(sel?(narrow?'撤选':'取消选用'):(narrow?'选用':'选用这套'),()=>toggleSel(v.id,o.id),sel?'on':'pri',
        {'aria-pressed':String(sel),'aria-label':sel?'取消选用方案 '+lab(i):'选用方案 '+lab(i)}),
      btn('编辑',()=>openO(v.id,o),'',{'aria-label':'编辑方案 '+lab(i)}),
      btn('复制',()=>dupOpt(v.id,o.id,i),'',{'aria-label':'复制方案 '+lab(i)}),
      btn('删除',()=>go({confirm:{t:'o',id:o.id}}),'',{'aria-label':'删除方案 '+lab(i)}));
  return h('div',{class:'opt'+(sel?' sel':'')},
    h('div',{class:'oh'},
      h('span',{class:'lb'},lab(i),sel?h('i',{},'★'):null),
      h('span',{class:'tag'},sel?'已选用':'备选')),
    h('div',{class:'ob'},
      fb('标题',o.title,'ft title',true),
      fb('封面短句',o.cover,'cover',true),
      fb('画面想法',o.idea,'ft')),
    acts);
}
function orow(v,o,i){
  const sel=v.selectedId===o.id;
  return h('div',{class:'orow'+(sel?' sel':'')},
    h('button',{type:'button',class:'omain','aria-label':'查看方案 '+lab(i),onclick:()=>go({mode:'one',start:i})},
      h('span',{class:'lb'},lab(i)),
      h('span',{class:'otx'},
        h('b',{class:'c2'},nm(o)),
        o.cover&&o.title?h('span',{class:'c1 mut'},'封面：'+o.cover):null)),
    btn(sel?'★':'☆',()=>toggleSel(v.id,o.id),'ic star'+(sel?' on':''),
      {'aria-pressed':String(sel),'aria-label':sel?'取消选用方案 '+lab(i):'选用方案 '+lab(i)}));
}
function videoView(S){
  const v=S.videos.find(x=>x.id===ui.vid);
  if(!v){ui.view='list';return listView(S);}
  const n=v.options.length;
  const mode=ui.mode==='all'?'all':'one';
  const start=clampN((ui.start|0),0,Math.max(0,n-per));
  ui.start=start;
  const end=Math.min(n,start+per);
  const seg=(t,k)=>h('button',{type:'button',class:mode===k?'on':'','aria-pressed':String(mode===k),
    onclick:()=>go({mode:k})},t);
  const ctl=paged&&n>0?h('div',{class:'ctl'},
    h('div',{class:'seg'},seg('逐套','one'),seg('总览','all')),
    mode==='one'?h('div',{class:'pg'},
      btn('‹',()=>go({start:start-1}),'ic',start<=0?{disabled:true,'aria-label':'上一套'}:{'aria-label':'上一套'}),
      h('span',{class:'pgt'},per>1&&end-start>1?(start+1)+'–'+end+'/'+n:(start+1)+'/'+n),
      btn('›',()=>go({start:start+1}),'ic',start+per>=n?{disabled:true,'aria-label':'下一套'}:{'aria-label':'下一套'})):null):null;
  const sel=selOf(v);
  const bar=h('div',{class:'bar'},
    btn('‹',()=>go({view:'list',vmenu:false,confirm:null}),'ic',{'aria-label':'返回视频列表'}),
    h('div',{class:'nm'},v.name),
    size==='6x3'?ctl:null,
    btn(narrow?'＋':'＋ 方案',()=>openO(v.id,null),'pri'+(narrow?' ic':''),{'aria-label':'新增一套方案'}),
    btn('⋯',()=>go({vmenu:!ui.vmenu,confirm:null}),'ic',{'aria-label':'更多：改名、删除视频','aria-expanded':String(!!ui.vmenu)}));
  const cv=ui.confirm&&ui.confirm.t==='v';
  const menu=ui.vmenu?h('div',{class:'menu'},
    cv?[h('span',{class:'warn'},'⚠ 删除整个视频及 '+n+' 套方案？'),
        btn('确认删除',()=>delVid(v.id),'danger'),btn('取消',()=>go({confirm:null}))]
      :[btn('改名',()=>openV(v)),btn('删除视频',()=>go({confirm:{t:'v'}}))]):null;
  let body;
